B.Q8=new A.e2("melody","Buzzer melody","Buzzer melody","Sound & light","Beginner","Play a short tune note by note.","Play a tune with tone()","V2 \xb7 Uno \xb7 ESP32","// Buzzer melody\n// Plays a short tune on the buzzer (pin 8).\nconst int BUZZER = 8;\n\nvoid note(int freq, int ms) {\n  tone(BUZZER, freq, ms);\n  delay(ms + 50);\n}\n\nvoid setup() {\n  pinMode(BUZZER, OUTPUT);\n}\n\nvoid loop() {\n  note(262, 400);\n  note(262, 400);\n  note(392, 400);\n  note(392, 400);\n  note(440, 400);\n  note(440, 400);\n  note(392, 800);\n  noTone(BUZZER);\n  delay(1500);\n}\n",null,B.XU,"BuzzerMelody",B.XS,null)
